1	#include "unigram_tokenizer.h"
2	#include <fstream>
3	#include <sstream>
4	#include <algorithm>
5	#include <cctype>
6	#include <limits>
7	#include <stdexcept>
8	
9	// --------- helpers ----------
10	static std::string Trim(const std::string& s) {
11	    size_t b = 0, e = s.size();
12	    while (b < e && std::isspace(static_cast<unsigned char>(s[b]))) ++b;
13	    while (e > b && std::isspace(static_cast<unsigned char>(s[e-1]))) --e;
14	    return s.substr(b, e - b);
15	}
16	
17	// 解析一行：将最后一个空白之后视为 logprob，其余为 token
18	static bool ParseTokenAndScore(const std::string& line, std::string& token, double& score) {
19	    std::string s = Trim(line);
20	    if (s.empty()) return false;
21	    // 找到最后一个空白
22	    size_t pos = s.find_last_of(" \t");
23	    if (pos == std::string::npos)
24	        return false;
25	    std::string tok = s.substr(0, pos);
26	    std::string num = s.substr(pos + 1);
27	    tok = Trim(tok);
28	    num = Trim(num);
29	    if (tok.empty() || num.empty())
30	        return false;
31	    try {
32	        score = std::stod(num);
33	    } catch (...) {
34	        return false;
35	    }
36	    token = tok;
37	    return true;
38	}
39	
40	// --------- UTF-8 ----------
41	bool UnigramTokenizer::IsAsciiSpace(unsigned char c) {
42	    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v';
43	}
44	
45	bool UnigramTokenizer::IsUnicodeSpace(uint32_t cp) {
46	    if (cp <= 0x7F) return IsAsciiSpace(static_cast<unsigned char>(cp));
47	    switch (cp) {
48	        case 0x00A0: case 0x1680:
49	        case 0x2000: case 0x2001: case 0x2002: case 0x2003:
50	        case 0x2004: case 0x2005: case 0x2006: case 0x2007:
51	        case 0x2008: case 0x2009: case 0x200A:
52	        case 0x2028: case 0x2029:
53	        case 0x202F: case 0x205F: case 0x3000:
54	            return true;
55	        default:
56	            return false;
57	    }
58	}
59	
60	bool UnigramTokenizer::NextUtf8(const std::string& s, size_t& i, uint32_t& cp, size_t& cp_len) {
61	    if (i >= s.size()) return false;
62	    unsigned char c0 = static_cast<unsigned char>(s[i]);
63	    if (c0 < 0x80) { cp = c0; cp_len = 1; ++i; return true; }
64	    else if ((c0 >> 5) == 0x6) {
65	        if (i + 1 >= s.size()) return false;
66	        unsigned char c1 = static_cast<unsigned char>(s[i+1]);
67	        if ((c1 & 0xC0) != 0x80) return false;
68	        cp = ((c0 & 0x1F) << 6) | (c1 & 0x3F); cp_len = 2; i += 2; return true;
69	    } else if ((c0 >> 4) == 0xE) {
70	        if (i + 2 >= s.size()) return false;
71	        unsigned char c1 = static_cast<unsigned char>(s[i+1]);
72	        unsigned char c2 = static_cast<unsigned char>(s[i+2]);
73	        if (((c1 & 0xC0) != 0x80) || ((c2 & 0xC0) != 0x80)) return false;
74	        cp = ((c0 & 0x0F) << 12) | ((c1 & 0x3F) << 6) | (c2 & 0x3F);
75	        cp_len = 3; i += 3; return true;
76	    } else if ((c0 >> 3) == 0x1E) {
77	        if (i + 3 >= s.size()) return false;
78	        unsigned char c1 = static_cast<unsigned char>(s[i+1]);
79	        unsigned char c2 = static_cast<unsigned char>(s[i+2]);
80	        unsigned char c3 = static_cast<unsigned char>(s[i+3]);
81	        if (((c1 & 0xC0) != 0x80) || ((c2 & 0xC0) != 0x80) || ((c3 & 0xC0) != 0x80)) return false;
82	        cp = ((c0 & 0x07) << 18) | ((c1 & 0x3F) << 12) | ((c2 & 0x3F) << 6) | (c3 & 0x3F);
83	        cp_len = 4; i += 4; return true;
84	    } else { return false; }
85	}
86	
87	// --------- Pretokenizer ----------
88	std::vector<std::string> UnigramTokenizer::PretokenizeSentencePiece(const std::string& text) {
89	    static const std::string ws_mark = "▁";
90	    std::vector<std::string> out;
91	    std::string curr;
92	    curr.reserve(text.size());
93	
94	    size_t i = 0;
95	    while (i < text.size()) {
96	        uint32_t cp; size_t len;
97	        if (!NextUtf8(text, i, cp, len)) break;
98	        if (IsUnicodeSpace(cp)) {
99	            if (!curr.empty()) {
100	                out.emplace_back(ws_mark + curr);
101	                curr.clear();
102	            }
103	        } else {
104	            curr.append(text, i - len, len);
105	        }
106	    }
107	    if (!curr.empty()) out.emplace_back(ws_mark + curr);
108	    return out;
109	}
110	
111	// --------- Model load ----------
112	void UnigramTokenizer::LoadModel(const std::string& model_path,
113	                                 std::vector<std::string>& tokens,
114	                                 std::vector<double>& scores) {
115	    std::ifstream fin(model_path);
116	    if (!fin) throw std::runtime_error("Failed to open unigram model file: " + model_path);
117	    tokens.clear(); scores.clear();
118	    tokens.reserve(100000); scores.reserve(100000);
119	    std::string line;
120	    std::string tok; double sc;
121	    while (std::getline(fin, line)) {
122	        if (!ParseTokenAndScore(line, tok, sc)) continue;
123	        tokens.push_back(tok);
124	        scores.push_back(sc);
125	    }
126	    if (tokens.empty()) throw std::runtime_error("Unigram model is empty: " + model_path);
127	}
128	
129	std::unordered_map<std::string, int> UnigramTokenizer::BuildTokenToId(const std::vector<std::string>& id_to_token) {
130	    std::unordered_map<std::string, int> m;
131	    m.reserve(id_to_token.size() * 2);
132	    for (int i = 0; i < static_cast<int>(id_to_token.size()); ++i) {
133	        m.emplace(id_to_token[i], i);
134	    }
135	    return m;
136	}
137	
138	void UnigramTokenizer::EnsureSpecialTokens(const SpecialTokensConfig& spec, bool add_if_missing) {
139	    auto ensure = [&](const std::optional<std::string>& name, int& id_slot) {
140	        if (!name.has_value()) { id_slot = -1; return; }
141	        auto it = token_to_id_.find(*name);
142	        if (it != token_to_id_.end()) {
143	            id_slot = it->second;
144	            return;
145	        }
146	        if (!add_if_missing) { id_slot = -1; return; }
147	        id_slot = static_cast<int>(id_to_token_.size());
148	        id_to_token_.push_back(*name);
149	        token_to_id_.emplace(*name, id_slot);
150	        token_logprob_.push_back(-1e9); // 特殊 token 给个极低分，避免影响分词
151	        // 追加到 trie 与否无所谓（一般不会在正文中出现）；这里追加也没问题
152	        AddToTrie(*name, id_slot);
153	    };
154	
155	    ensure(spec.bos_token, special_ids_.bos_id);
156	    ensure(spec.eos_token, special_ids_.eos_id);
157	    ensure(spec.unk_token, special_ids_.unk_id);
158	    ensure(spec.sep_token, special_ids_.sep_id);
159	    ensure(spec.pad_token, special_ids_.pad_id);
160	    ensure(spec.cls_token, special_ids_.cls_id);
161	    ensure(spec.mask_token, special_ids_.mask_id);
162	}
163	
164	// --------- Trie ----------
165	void UnigramTokenizer::BuildTrie() {
166	    trie_.clear();
167	    trie_.emplace_back(); // root
168	    for (int id = 0; id < static_cast<int>(id_to_token_.size()); ++id) {
169	        AddToTrie(id_to_token_[id], id);
170	    }
171	}
172	
173	void UnigramTokenizer::AddToTrie(const std::string& token, int token_id) {
174	    int node = 0;
175	    for (unsigned char c : token) {
176	        int nxt = trie_[node].next[c];
177	        if (nxt == -1) {
178	            nxt = static_cast<int>(trie_.size());
179	            trie_[node].next[c] = nxt;
180	            trie_.emplace_back();
181	        }
182	        node = nxt;
183	    }
184	    trie_[node].token_id = token_id; // 唯一 token
185	}
186	
187	void UnigramTokenizer::MatchAt(const std::string& s, size_t pos, std::vector<std::pair<int,int>>& out_matches) const {
188	    out_matches.clear();
189	    int node = 0;
190	    for (size_t i = pos; i < s.size(); ++i) {
191	        unsigned char c = static_cast<unsigned char>(s[i]);
192	        int nxt = trie_[node].next[c];
193	        if (nxt == -1) break;
194	        node = nxt;
195	        if (trie_[node].token_id >= 0) {
196	            int tid = trie_[node].token_id;
197	            int len = static_cast<int>(i + 1 - pos);
198	            out_matches.emplace_back(tid, len);
199	        }
200	    }
201	}
202	
203	// --------- Move semantics ----------
204	UnigramTokenizer::UnigramTokenizer(UnigramTokenizer&& other) noexcept
205	    : id_to_token_(std::move(other.id_to_token_)),
206	      token_to_id_(std::move(other.token_to_id_)),
207	      token_logprob_(std::move(other.token_logprob_)),
208	      trie_(std::move(other.trie_)),
209	      special_ids_(other.special_ids_),
210	      fallback_to_chars_(other.fallback_to_chars_),
211	      unk_penalty_(other.unk_penalty_) {
212	    std::lock_guard<std::mutex> lk(other.cache_mu_);
213	    piece_cache_ = std::move(other.piece_cache_);
214	}
215	
216	UnigramTokenizer& UnigramTokenizer::operator=(UnigramTokenizer&& other) noexcept {
217	    if (this != &other) {
218	        std::scoped_lock lk(cache_mu_, other.cache_mu_);
219	        id_to_token_ = std::move(other.id_to_token_);
220	        token_to_id_ = std::move(other.token_to_id_);
221	        token_logprob_ = std::move(other.token_logprob_);
222	        trie_ = std::move(other.trie_);
223	        special_ids_ = other.special_ids_;
224	        fallback_to_chars_ = other.fallback_to_chars_;
225	        unk_penalty_ = other.unk_penalty_;
226	        piece_cache_ = std::move(other.piece_cache_);
227	    }
228	    return *this;
229	}
230	
231	// --------- Load ----------
232	UnigramTokenizer UnigramTokenizer::LoadFromFile(const std::string& model_path,
233	                                                const SpecialTokensConfig& spec,
234	                                                bool add_special_if_missing,
235	                                                bool fallback_to_chars,
236	                                                double unk_penalty) {
237	    UnigramTokenizer tok;
238	    std::vector<std::string> toks;
239	    std::vector<double> scores;
240	    LoadModel(model_path, toks, scores);
241	
242	    tok.id_to_token_ = std::move(toks);
243	    tok.token_logprob_ = std::move(scores);
244	    tok.token_to_id_ = BuildTokenToId(tok.id_to_token_);
245	    tok.fallback_to_chars_ = fallback_to_chars;
246	    tok.unk_penalty_ = unk_penalty;
247	
248	    tok.BuildTrie();
249	    tok.EnsureSpecialTokens(spec, add_special_if_missing);
250	    // 显式 move，避免编译器尝试拷贝（MSVC）
251	    return std::move(tok);
252	}
253	
254	// --------- Viterbi segmentation for one piece ----------
255	const std::vector<std::string>& UnigramTokenizer::SegmentPieceCached(const std::string& piece) const {
256	    {
257	        std::lock_guard<std::mutex> g(cache_mu_);
258	        auto it = piece_cache_.find(piece);
259	        if (it != piece_cache_.end()) return it->second;
260	    }
261	    auto seg = SegmentPiece(piece);
262	    {
263	        std::lock_guard<std::mutex> g(cache_mu_);
264	        auto [it, _] = piece_cache_.emplace(piece, std::move(seg));
265	        return it->second;
266	    }
267	}
268	
269	std::vector<std::string> UnigramTokenizer::SegmentPiece(const std::string& piece) const {
270	    const int n = static_cast<int>(piece.size());
271	    if (n == 0) return {};
272	
273	    // dp[i]: 从 i 开始的最佳 log 概率；back_len[i]：选择的 token 长度；back_tid[i]：token id（<0 表示未知回退）
274	    std::vector<double> dp(n + 1, -std::numeric_limits<double>::infinity());
275	    std::vector<int> back_len(n + 1, 0);
276	    std::vector<int> back_tid(n + 1, -1);
277	    dp[n] = 0.0;
278	
279	    std::vector<std::pair<int,int>> matches; // (token_id, len)
280	
281	    for (int i = n - 1; i >= 0; --i) {
282	        // 收集匹配
283	        MatchAt(piece, static_cast<size_t>(i), matches);
284	
285	        if (!matches.empty()) {
286	            for (const auto& m : matches) {
287	                int tid = m.first;
288	                int len = m.second;
289	                double cand = token_logprob_[tid] + dp[i + len];
290	                if (cand > dp[i]) {
291	                    dp[i] = cand;
292	                    back_len[i] = len;
293	                    back_tid[i] = tid;
294	                }
295	            }
296	        } else {
297	            // 没有任何匹配：回退到单个 UTF-8 字符
298	            size_t pos = static_cast<size_t>(i);
299	            uint32_t cp; size_t cplen = 1;
300	            if (!NextUtf8(piece, pos, cp, cplen)) {
301	                // 字节异常，作为单字节处理
302	                cplen = 1;
303	            }
304	            std::string ch = piece.substr(i, static_cast<size_t>(cplen));
305	            auto itc = token_to_id_.find(ch);
306	            if (itc != token_to_id_.end()) {
307	                int tid = itc->second;
308	                double cand = token_logprob_[tid] + dp[i + static_cast<int>(cplen)];
309	                if (cand > dp[i]) {
310	                    dp[i] = cand;
311	                    back_len[i] = static_cast<int>(cplen);
312	                    back_tid[i] = tid;
313	                }
314	            } else {
315	                // 使用 UNK 罚分路径
316	                double cand = unk_penalty_ + dp[i + static_cast<int>(cplen)];
317	                if (cand > dp[i]) {
318	                    dp[i] = cand;
319	                    back_len[i] = static_cast<int>(cplen);
320	                    back_tid[i] = -1; // 未知
321	                }
322	            }
323	        }
324	    }
325	
326	    // 回溯
327	    std::vector<std::string> tokens;
328	    tokens.reserve(n / 2 + 4);
329	    int i = 0;
330	    while (i < n) {
331	        int len = back_len[i];
332	        if (len <= 0) {
333	            // 安全兜底：前进一个 UTF-8 字符或字节
334	            size_t pos = static_cast<size_t>(i);
335	            uint32_t cp; size_t cplen = 1;
336	            if (!NextUtf8(piece, pos, cp, cplen)) cplen = 1;
337	            tokens.emplace_back(piece.substr(i, cplen));
338	            i += static_cast<int>(cplen);
339	            continue;
340	        }
341	        tokens.emplace_back(piece.substr(i, len));
342	        i += len;
343	    }
344	    return tokens;
345	}
346	
347	// --------- Tokens -> IDs ----------
348	void UnigramTokenizer::TokensToIds(const std::vector<std::string>& tokens, std::vector<int>& out) const {
349	    out.reserve(out.size() + tokens.size());
350	    for (const auto& t : tokens) {
351	        auto it = token_to_id_.find(t);
352	        if (it != token_to_id_.end()) {
353	            out.push_back(it->second);
354	        } else if (fallback_to_chars_) {
355	            // t 可能是单个 UTF-8 字符（SegmentPiece 在 OOV 时按字符推进）
356	            size_t pos = 0; uint32_t cp; size_t cplen;
357	            if (!NextUtf8(t, pos, cp, cplen)) {
358	                cplen = t.size();
359	            }
