int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " unigram_model.txt [text]\n";
        return 1;
    }
    std::string model_path = argv[1];
    std::string text = (argc >= 3) ? argv[2] : "Hello 世界! 안녕하세요 こんにちは ▁xxxx abc ";

    SpecialTokensConfig spec;
